reference_solution:
def longest_binary_subsequence_at_most(s,k):
    answer=s.count('0');value=0;place=1
    for char in reversed(s):
        if char=='1' and value+place<=k:answer+=1;value+=place
        if place<=k:place*=2
    return answer

